import{_ as t,o as a,c as i,a5 as r}from"./chunks/framework.UjrY2eRK.js";const p=JSON.parse('{"title":"Push Gateway UI remote state","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/ui-remote-state.md","filePath":"architecture/ui-remote-state.md","lastUpdated":1788228339000}'),o={name:"architecture/ui-remote-state.md"};function s(n,e,d,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="push-gateway-ui-remote-state" tabindex="-1">Push Gateway UI remote state <a class="header-anchor" href="#push-gateway-ui-remote-state" aria-label="Permalink to &quot;Push Gateway UI remote state&quot;">​</a></h1><p>Overview and Metrics use one deep remote-state module for the complete read lifecycle. A page supplies only a generated-client request and, for Metrics, the existing predicate that says whether its selected UTC range is current enough to poll.</p><p>The module owns:</p><ul><li>the initial visible load and the idle, loading, fresh, stale, and error states;</li><li>retention of the last successful observation when a refresh fails;</li><li>explicit retry through the same refresh path;</li><li>immediate refresh when a hidden document becomes visible;</li><li>30-second polling only while visible; and</li><li>one shared in-flight request across automatic polling and explicit refresh, with one latest-range refresh queued when Metrics parameters change.</li></ul><p>The generated Overview and Metrics clients therefore remain transport adapters. They return one typed observable per request and neither retain data nor decide when a request occurs. Pages consume only the module&#39;s <code>state</code>, <code>data</code>, and <code>refresh</code> interface.</p><h2 id="proof-and-migration-decision" tabindex="-1">Proof and migration decision <a class="header-anchor" href="#proof-and-migration-decision" aria-label="Permalink to &quot;Proof and migration decision&quot;">​</a></h2><p>The proof removed page-owned <code>DestroyRef</code> subscriptions, visibility-event and timer composition, duplicated fresh-or-stale extraction, and the race between polling and Retry. Focused interface tests exercise first-load failure, stale retention, retry, hidden-to-visible refresh, visibility-paused polling, Metrics&#39; current-range predicate, same-query overlap suppression, and latest-range queueing behind an older request. The existing browser suite continues to exercise Overview loading, stale recovery and Retry, plus populated, filtered, and empty Metrics views.</p><p>This is enough leverage for the two continuously observed read capabilities, but not evidence for a broad migration yet. Configuration is a one-time read; Operations coordinates reads with Operator Actions; Security owns session revocation and append-only audit pagination. Extending the interface for those unshared behaviors would be hypothetical. Their existing manual resources stay in place until a separately scoped change can demonstrate a shared production need without widening this interface.</p>',8)])])}const m=t(o,[["render",s]]);export{p as __pageData,m as default};
